async function createMockSession(
  dir: string,
  sessionId: string,
  cwd: string,
  commands: string[],
): Promise<string> {
  const sessionDir = join(dir, cwd.replace(/^\//, "--").replace(/\//g, "-") + "--");
  await mkdir(sessionDir, { recursive: true });
  const filePath = join(sessionDir, `2026-07-15T10-00-00-000Z_${sessionId}.jsonl`);

  const lines = [
    `{"type":"session","version":3,"id":"${sessionId}","timestamp":"2026-07-15T10:00:00.000Z","cwd":"${cwd}"}`,
  ];

  for (let i = 0; i < commands.length; i++) {
    lines.push(
      `{"type":"message","id":"m${i}","parentId":null,"timestamp":"2026-07-15T10:00:${String(10 + i).padStart(2, "0")}.000Z","message":{"role":"assistant","content":[{"type":"toolCall","id":"call_${i}","name":"bash","arguments":{"command":"${commands[i]}"}}]}}`,
    );
  }

  await writeFile(filePath, lines.join("\n") + "\n");
  return filePath;
}

edits.newText:
async function createMockSession(
  dir: string,
  sessionId: string,
  cwd: string,
  commands: string[],
): Promise<string> {
  const sessionDir = join(dir, cwd.replace(/^\//, "--").replace(/\//g, "-") + "--");
  await mkdir(sessionDir, { recursive: true });
  // Use current timestamp to ensure it falls within the 7-day bucket window
  const now = new Date();
  const ts = now.toISOString();
  const fileTs = ts.replace(/:/g, "-");
  const filePath = join(sessionDir, `${fileTs}_${sessionId}.jsonl`);

  const lines = [
    `{"type":"session","version":3,"id":"${sessionId}","timestamp":"${ts}","cwd":"${cwd}"}`,
  ];

  for (let i = 0; i < commands.length; i++) {
    const msgTs = new Date(now.getTime() + (i + 1) * 1000).toISOString();
    lines.push(
      `{"type":"message","id":"m${i}","parentId":null,"timestamp":"${msgTs}","message":{"role":"assistant","content":[{"type":"toolCall","id":"call_${i}","name":"bash","arguments":{"command":"${commands[i]}"}}]}}`,
    );
  }

  await writeFile(filePath, lines.join("\n") + "\n");
  return filePath;
}

